using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Divergence;

internal sealed class MaximalHockeyStickArbitrarySupportDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/Divergence/MaximalHockeyStickArbitrarySupport.";
    private static readonly LibraryNoteRef Source =
        LibraryNoteRef.Create("D5/L/Divergence/hiaimosonyitomamichel2026hockeystick");
    private static readonly LibraryNoteRef Matsumoto =
        LibraryNoteRef.Create("D5/L/Divergence/matsumoto2018newquantumfdivergence");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "At a real finite actual original-L1 maximal value, equality with the integrated original operational hockey infima is equivalent to the finite Loewner-secant condition on the actual arbitrary curvature support.",
        H("The arbitrary-support original-L1 equality classifier"), Blocks(
            Paragraph(Text("Fix any finite output type n, PSD complex matrices A,B of arbitrary trace, and any real f convex on the positive ray. The source universe u is arbitrary and independent of the output universe. originalL1Value is the EReal infimum of the actual closed-perspective cost over every sigma-finite measurable source and every positive complex-linear TP map defined on its entire complex L1 space, with nonnegative inputs preparing A,B. originalHockeyValue integrates the infima of the original positive and negative L1 hockey costs, not a proxy source class. The curvature is the actual Stieltjes measure constructed from the right derivative of f. Its entire atom at one belongs to the negative branch. Singular and zero pairs, empty output dimension, unnormalized masses and infinite scalar endpoint costs remain in scope.")),
            Paragraph(Text("Write X(t)=MaximalHockeyStickLoewnerSlopes.optimalOverlap A B hA hB t and K=support(curvature hf). The criterion quantifies every finite strictly increasing tuple 0=t_0<t_1<...<t_m with each positive knot in K, including m=0. The actual matrix secants D_i=(X(t_(i+1))-X(t_i))/(t_(i+1)-t_i) must satisfy 0<=D_i<=B and be antitone in Loewner order. K may be empty; zero and infinity are not curvature points. The theorem keeps the real finite hypothesis originalL1Value=c. It does not assert necessity from equality of infinite values or replace this support-dependent condition by the older full-support commutator criterion.")),
            Node("prepared_trace_lower_tail_linear", "A finite witness below all its positive ratios",
                "For an actual finite test W, a positive r, and 0<=t<=r, if each label has p_i=0 or r q_i<=p_i, then the prepared-overlap trace at t is (t/r) times its trace at r. Zero p labels remain present. The result is used to compare lower-tail negative hinges without requiring finite scalar endpoint limits.", true),
            Node("prepared_trace_upper_tail_constant", "A finite witness above all its finite ratios",
                "For r<=t, if each label has q_i=0 or p_i<=r q_i, the actual prepared-overlap trace at t equals its trace at r. Labels on the q=0 axis remain present. This supplies the upper-tail positive-hinge comparison.", true),
            Node("lower_hinge_tail_dominated", "Lower-tail domination from an actual anchor",
                "If W is linear below a positive anchor r and a second actual test R has at least W's prepared-overlap trace at r, then at every 0<=t<=r its negative hinge t Tr(B)-Tr(R.preparedOverlap t) is bounded above by W's negative hinge. This uses concavity of each min(p,tq), with both tests preparing the same original matrices.", true),
            Node("upper_hinge_tail_dominated", "Upper-tail domination from an actual anchor",
                "If W is constant above r and R has at least its prepared trace at r, then for t>=r the positive hinge Tr(A)-Tr(R.preparedOverlap t) is bounded above by W's positive hinge. Monotonicity supplies the comparison and retains q=0 labels.", true),
            Paragraph(Text("Sufficiency first obtains one actual finite-cost witness W from the real finite maximal infimum, using the existing source-class equivalence and approximate_finite_tests. Its finite ratios give positive cutoffs below one and above one. Each effective tail either has a true support anchor beyond the witness ratios or contains no support points and is discarded only using the conullity of the actual support. Every finite interpolation test includes all available anchors and an increasing finite part of a dense support sequence. The explicit finite-knot theorem supplies these tests without assuming a simultaneous optimizer.")),
            Paragraph(Text("The proof controls the literal nonnegative test kernels, not just their gaps. An integrable envelope is E(t)=testKernel W(t)+1_[a,b](t)(Tr(A)+b Tr(B)). Local finiteness makes the compact middle term integrable; the two anchor comparisons bound the tails at support points by W's integrable kernel. The same envelope controls the gaps and proves every interpolating test has finite actual closed-perspective cost. Uniform Lipschitz continuity and eventual exact interpolation yield pointwise gap convergence on the support by the pinned mathlib EquicontinuousAt.tendsto_of_mem_closure theorem. Dominated convergence sends the curvature gap integrals to zero; the existing exact finite_cost_gap identity then sandwiches the actual infimum against the operational hockey value. For empty support the curvature measure is zero and the same exact cost identity closes the argument directly.")),
            Node("finiteLoewnerSlopes_implies_original_eq", "Sufficiency for the original source class",
                "For any real c with originalL1Value hf A B=c, FiniteLoewnerSlopes on the actual curvature support implies originalL1Value=originalHockeyValue. The proof transfers the finite infimum equality through originalL1Value_eq_allL1Value, allL1Value_eq_maximalValue and hockeyValue_eq_original_operational. The finite value is a hypothesis about the actual original infimum, not an optimizer or endpoint-finiteness premise.", true),
            Node("original_eq_iff_finiteLoewnerSlopes", "Exact arbitrary-support equivalence",
                "For every real convex generator, arbitrary finite PSD output pair and real c satisfying originalL1Value=c, equality of originalL1Value with originalHockeyValue holds if and only if every finite ordered tuple in the actual curvature support with virtual initial zero has PSD, B-bounded, antitone optimal-overlap matrix secants. MaximalHockeyStickLoewnerSlopes.original_eq_implies_finiteLoewnerSlopes proves necessity; the witness-controlled approximation above proves sufficiency. There is no full-support, operator-convexity, faithfulness, normalization, nonempty-dimension, finite-endpoint, attainment, section or simultaneous-optimizer assumption, and no interchange of an infimum with integration.", true),
            Paragraph(Text("Attribution: the equality question and direct positive-L1 three-component hockey construction are from Hiai, Mosonyi and Tomamichel, Hockey stick f-divergences, arXiv:2607.08760v1, especially Proposition V.1 and the final equality question. Matsumoto, arXiv:1311.4722v4, p. 8, Lemma 4.1, is the one-cost compression antecedent; the already established original/s-finite/finite source equivalence is reused, together with its finite-moment implementation. The full-support commutation theorem remains a separate earlier result. This arbitrary-support result is a repository classification at the stated real-finite scope; worldwide novelty is unverified."))
        )));

    private static DocumentBlock Node(string name, string heading, string prose, bool theorem) =>
        Describe.Lean(DescribeId.Create("maximal-hockey-arbitrary-support-" + name.Replace("_", "-").ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(heading), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(Source, Matsumoto), Blocks(Paragraph(Text(prose))),
            theorem ? DescribeRole.Theorem : DescribeRole.Definition);
}
